		agent, err := Detect(context.Background())
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		if agent.Name() != types.AgentName("detectable") {
			t.Errorf("expected Name() %q, got %q", "detectable", agent.Name())
		}
	})
}

