59	// SaveSessionState saves the session state atomically.
60	func SaveSessionState(ctx context.Context, state *SessionState) error {
61		// Validate session ID to prevent path traversal
62		if err := validation.ValidateSessionID(state.SessionID); err != nil {
63			return fmt.Errorf("invalid session ID: %w", err)
64		}
65	
66		stateDir, err := getSessionStateDir(ctx)
67		if err != nil {
68			return fmt.Errorf("failed to get session state directory: %w", err)
69		}
70	
71		if err := os.MkdirAll(stateDir, 0o750); err != nil {
72			return fmt.Errorf("failed to create session state directory: %w", err)
73		}
74	
75		data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
76		if err != nil {
77			return fmt.Errorf("failed to marshal session state: %w", err)
78		}
79	
80		stateFile, err := sessionStateFile(ctx, state.SessionID)
81		if err != nil {
82			return fmt.Errorf("failed to get session state file path: %w", err)
83		}
84	
85		// Atomic write: write to temp file, then rename
86		tmpFile := stateFile + ".tmp"
87		if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
88			return fmt.Errorf("failed to write session state: %w", err)
89		}
90		if err := os.Rename(tmpFile, stateFile); err != nil {
91			return fmt.Errorf("failed to rename session state file: %w", err)
92		}
93		return nil
94	}
95	
96	// ListSessionStates returns all session states from the state directory.
97	// This is a package-level function that doesn't require a specific strategy instance.
98	func ListSessionStates(ctx context.Context) ([]*SessionState, error) {
99		store, err := session.NewStateStore(ctx)
100		if err != nil {
101			return nil, fmt.Errorf("failed to create state store: %w", err)
102		}
103	
104		states, err := store.List(ctx)
105		if err != nil {
106			return nil, fmt.Errorf("failed to list session states: %w", err)
107		}
108		return states, nil
109	}
110	
111	// FindMostRecentSession returns the session ID of the most recently interacted session
112	// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
113	// Scoping to the current worktree prevents cross-worktree pollution in log routing.
114	// Falls back to unfiltered search if the worktree path can't be determined.
115	func FindMostRecentSession(ctx context.Context) string {
116		states, err := ListSessionStates(ctx)
117		if err != nil || len(states) == 0 {
118			return ""
119		}
120	
121		// Scope to current worktree to prevent cross-worktree pollution.
122		worktreePath, wpErr := paths.WorktreeRoot(ctx)
123		if wpErr == nil && worktreePath != "" {
124			var filtered []*SessionState
125			for _, s := range states {
126				if s.WorktreePath == worktreePath {
127					filtered = append(filtered, s)
128				}
129			}
130			if len(filtered) > 0 {
131				states = filtered
132			}
133			// If no sessions match the worktree, fall back to all sessions
134		}
135	
136		var best *SessionState
137		for _, s := range states {
138			if s.LastInteractionTime == nil {
139				continue
140			}
141			if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
142				best = s
143			}
144		}
145		if best != nil {
146			return best.SessionID
147		}
148	
149		// Fallback: return most recently started session
150		for _, s := range states {
151			if best == nil || s.StartedAt.After(best.StartedAt) {
152				best = s
153			}
154		}
155		if best != nil {
156			return best.SessionID
157		}
158		return ""
159	}
160	
161	// TransitionAndLog runs a session phase transition, applies actions via the
162	// handler, and logs the transition. Returns the first handler error from
163	// ApplyTransition (if any) so callers can surface it. The error is also
164	// logged internally for diagnostics.
165	// This is the single entry point for all state machine transitions to ensure
166	// consistent logging of phase changes.
167	func TransitionAndLog(goCtx context.Context, state *SessionState, event session.Event, ctx session.TransitionContext, handler session.ActionHandler) error {
168		oldPhase := state.Phase
169		result := session.Transition(oldPhase, event, ctx)
170		logCtx := logging.WithComponent(goCtx, "session")
