173		if handlerErr != nil {
174			logging.Error(logCtx, "action handler error during transition",
175				slog.String("session_id", state.SessionID),
176				slog.String("event", event.String()),
177				slog.Any("error", handlerErr),
178			)
179		}
180	
181		if result.NewPhase != oldPhase {
