192				slog.String("phase", string(result.NewPhase)),
193				slog.Any("result", result),
194			)
195		}
196	
197		if handlerErr != nil {
198			return fmt.Errorf("transition %s: %w", event, handlerErr)
199		}
200		return nil
201	}
